(7356793, 1151569, 151548, '<td valign="top">The lift of the fronds at the ends into a silver light lifts this to a 9 for me. Nice composition.</td>', 'The lift of the fronds at the ends into a silver light lifts this to a 9 for me. Nice composition.', '2015-06-03 07:09:30.000000', NULL, 1),
(7356794, 1151607, 151548, '<td valign="top">Well observed and executed.</td>', 'Well observed and executed.', '2015-06-03 07:10:26.000000', NULL, 1),
(7356796, 1151790, 151548, '<td valign="top">I find it a little intrusive, which bothers me but well executed. The reflections on the polished gravestones and the composition especially.</td>', 'I find it a little intrusive, which bothers me but well executed. The reflections on the polished gravestones and the composition especially.', '2015-06-03 07:13:00.000000', NULL, 1),
(7356797, 1151657, 135744, '<td valign="top">Very nice indeed</td>', 'Very nice indeed', '2015-06-03 07:13:25.000000', NULL, 1),
(7356798, 1151666, 151548, '<td valign="top">You have captured the loneliness and sense of menace of these types of buildings. I can hear the footsteps echoing along the corridor.</td>', 'You have captured the loneliness and sense of menace of these types of buildings. I can hear the footsteps echoing along the corridor.', '2015-06-03 07:15:21.000000', NULL, 1),
(7356799, 1151718, 135744, '<td valign="top">Super processing and lovely mist and of course the perfect subject in mist/fog - some cows. Very nicely done.</td>', 'Super processing and lovely mist and of course the perfect subject in mist/fog - some cows. Very nicely done.', '2015-06-03 07:15:49.000000', NULL, 1),
