(7356805, 1151342, 151548, '<td valign="top">I love the colours but the image does not have the strength to carry the soft focus for me.</td>', 'I love the colours but the image does not have the strength to carry the soft focus for me.', '2015-06-03 07:21:48.000000', NULL, 1),
