(7356848, 1151192, 15711, '<td valign="top">I love him running out of the shot.  Homage to Bruce Jenner (now Caitlyn) ;)</td>', 'I love him running out of the shot.  Homage to Bruce Jenner (now Caitlyn) ;)', '2015-06-03 09:42:38.000000', NULL, 1),
