(7356927, 1151340, 16046, '<td valign="top">Top 2</td>', 'Top 2', '2015-06-03 12:39:25.000000', NULL, 1),
(7356928, 1151657, 16046, '<td valign="top">Top 3</td>', 'Top 3', '2015-06-03 12:40:58.000000', NULL, 1),
(7356950, 1151665, 177322, '<td valign="top">Just have to chuckle at all those toe stretches. Really adorable babies. That array of legs makes for interesting elements in the composition. Good luck with this.</td>', 'Just have to chuckle at all those toe stretches. Really adorable babies. That array of legs makes for interesting elements in the composition. Good luck with this.', '2015-06-03 13:20:59.000000', NULL, 1),
(7356952, 1151342, 177322, '<td valign="top">Oh, this is pure contentment.  Reminds me of fishing with my grandfather when I was a wee lass.  In the Styrofoam cooler would be a bologna sandwich smeared with yellow mustard and a thermos of cold milk for lunch.  Looks like it is about time to eat.<br/> <br/>The design element of the crossed oars and bow of the boat really direct the viewer''s eyes to the serenity of this incredibly lovely pond.  Hope this ribbons for you.</td>', 'Oh, this is pure contentment.  Reminds me of fishing with my grandfather when I was a wee lass.  In the Styrofoam cooler would be a bologna sandwich smeared with yellow mustard and a thermos of cold milk for lunch.  Looks like it is about time to eat. The design element of the crossed oars and bow of the boat really direct the viewer''s eyes to the serenity of this incredibly lovely pond.  Hope this ribbons for you.', '2015-06-03 13:23:32.000000', NULL, 1),
(7356954, 1151812, 122678, '<td valign="top">This is an absolutely perfect image. Beautifully composed in everyway and perfect for this challange. I love the use of color, the breeze, the crop is not too centered, its natural.<br/>I hope you win. <br/>good luck</td>', 'This is an absolutely perfect image. Beautifully composed in everyway and perfect for this challange. I love the use of color, the breeze, the crop is not too centered, its natural.I hope you win. good luck', '2015-06-03 13:27:07.000000', NULL, 1),
